import _codecs
calls = []
class Mapping:
    def __getitem__(self, key):
        calls.append(key)
        assert input() == 'ready'
        return -1
try:
    _codecs.charmap_encode('A', 'strict', Mapping())
except TypeError as error:
    assert error.args == ("character mapping must be in range(256)",)
else:
    raise AssertionError('mapping accepted')
assert calls == [65]
print('verified')

